 * @param {number} left
 * @param {number} right
 * @return {string}
 */
var abbreviateProduct = function(left, right) {
    let cnt2 = 0, cnt5 = 0;
    let suffix = 1n;
    const MOD = 1000000000000n; // keep enough digits for last 10-12 significant digits
    const KEEP = 15n;

    for (let x = left; x <= right; x++) {
        let n = x;

        while (n % 2 === 0) {
            cnt2++;
            n /= 2;
        }
        while (n % 5 === 0) {
            cnt5++;
            n /= 5;
        }

        suffix = (suffix * BigInt(n)) % MOD;
    }

    const zeros = Math.min(cnt2, cnt5);
    const extra2 = cnt2 - zeros;
    const extra5 = cnt5 - zeros;

    for (let i = 0; i < extra2; i++) suffix = (suffix * 2n) % MOD;
    for (let i = 0; i < extra5; i++) suffix = (suffix * 5n) % MOD;

    // remove any remaining trailing zeros introduced by modular truncation
    while (suffix % 10n === 0n) suffix /= 10n;

    let s = suffix.toString();
    const digits = s.length;

    if (digits > 10) {
        s = s.slice(0, 5) + "..." + s.slice(-5);
    }

    return s + "e" + zeros.toString() + " ";
};
