var maxScore = function(nums) {
    const m = nums.length;
    const n = m >> 1;

    function gcd(a, b) {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    const pairGcd = Array.from({ length: m }, () => Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            pairGcd[i][j] = gcd(nums[i], nums[j]);
        }
    }

    const size = 1 << m;
    const memo = new Array(size).fill(-1);

    function dfs(mask) {
        if (mask === size - 1) return 0;
        if (memo[mask] !== -1) return memo[mask];

        let first = 0;
        while (mask & (1 << first)) first++;

        let op = (popcount(mask) >> 1) + 1;
        let best = 0;

        for (let j = first + 1; j < m; j++) {
            if ((mask & (1 << j)) === 0) {
                const newMask = mask | (1 << first) | (1 << j);
                best = Math.max(best, op * pairGcd[first][j] + dfs(newMask));
            }
        }

        memo[mask] = best;
        return best;
    }

    const popcount = new Array(size).fill(0);
    for (let i = 1; i < size; i++) {
        popcount[i] = popcount[i >> 1] + (i & 1);
    }

    return dfs(0);
};
