var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    const n = flowers.length;
    const arr = flowers.slice().sort((a, b) => a - b);

    let complete = 0;
    while (complete < n && arr[n - 1 - complete] >= target) complete++;

    if (complete === n) return n * full;

    const m = n - complete; // only these can be incomplete
    const prefix = new Array(m + 1).fill(0);
    for (let i = 0; i < m; i++) prefix[i + 1] = prefix[i] + arr[i];

    // If all are complete, partial contribution is 0
    let ans = complete * full;

    // Binary search maximum minimum level for first k incomplete gardens
    function can(level, k, budget) {
        // raise arr[0..k-1] to at least level
        let l = 0, r = k;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (arr[mid] <= level) l = mid + 1;
            else r = mid;
        }
        const idx = l;
        const cost = level * idx - prefix[idx];
        return cost <= budget;
    }

    let usedForComplete = 0;
    for (let i = 0; i <= complete; i++) {
        if (i > 0) {
            usedForComplete += target - arr[n - i];
        }
        if (usedForComplete > newFlowers) break;

        const budget = newFlowers - usedForComplete;
        const remaining = n - i;
        if (remaining === 0) {
            ans = Math.max(ans, i * full);
