    const safe = new Array(n).fill(false);

    while (head < queue.length) {
        const node = queue[head++];
        safe[node] = true;
        for (const prev of rev[node]) {
            outDegree[prev]--;
            if (outDegree[prev] === 0) queue.push(prev);
        }
    }

    const ans = [];
    for (let i = 0; i < n; i++) {
        if (safe[i]) ans.push(i);
    }
    return ans;
