 * @param {number} m
 * @param {number} k
 * @return {number}
 */
var minDays = function(bloomDay, m, k) {
    const n = bloomDay.length;
    if (m * k > n) return -1;

    let left = Infinity, right = -Infinity;
    for (const d of bloomDay) {
        if (d < left) left = d;
        if (d > right) right = d;
    }

    const canMake = (day) => {
        let bouquets = 0, consecutive = 0;
        for (let i = 0; i < n; i++) {
            if (bloomDay[i] <= day) {
                consecutive++;
                if (consecutive === k) {
                    bouquets++;
                    if (bouquets >= m) return true;
                    consecutive = 0;
                }
            } else {
                consecutive = 0;
            }
        }
        return false;
    };

    let ans = -1;
    while (left <= right) {
        const mid = left + Math.floor((right - left) / 2);
        if (canMake(mid)) {
            ans = mid;
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    return ans;
};
